theorem subset_characterGenericFibre (S : Set (F ⊗[O] A →ₐ[F] L)) :
    {w | ∀ x ∈ vanishingIdealOfPoints S, CartierDual.dualBaseChangeLin O F A w x = 0}
      ⊆ (characterGenericFibre O F A L S : Set (F ⊗[O] CartierDual O A))

theorem heckeGen_sub_C_mem_awayIdeal {S : Finset Nat.Primes} {𝔪 : Ideal HeckeAlg} {ℓ : Nat.Primes}
    (hℓ : ℓ ∉ S) {b : ℤ} (hb : heckeGen ℓ - MvPolynomial.C b ∈ 𝔪) :
    heckeGen ℓ - MvPolynomial.C b ∈ awayIdeal S 𝔪

theorem mem_anemicContraction {S : Finset Nat.Primes} {𝔪 : Ideal HeckeAlg}
    {t : MvPolynomial {ℓ : Nat.Primes // ℓ ∉ S} ℤ} :
    t ∈ anemicContraction S 𝔪 ↔ anemicInclusion S t ∈ 𝔪

theorem smul_sub_self_mem_toricMonodromyPart {q : ℕ} {I : Subgroup G} {σ : G} (hσ : σ ∈ I) {x : J}
    {m : ℕ} (hm : 0 < m) (hmq : m.Coprime q) (hx : m • x = 0) :
    σ • x - x ∈ toricMonodromyPart (J := J) q I
